class Solution:
    def doubleIt(self, head: Optional[ListNode]) -> Optional[ListNode]:
        def helper(node):
            if not node:
                return 0
            carry = helper(node.next)
            total = node.val * 2 + carry
            node.val = total % 10
            return total // 10
        carry = helper(head)
        if carry:
            new_head = ListNode(carry)
            new_head.next = head
            return new_head
        return head

